const rows = $input.all();

const rutas = {};

let montoTotal = 0;
let aprobaciones = 0;

for (const item of rows) {
  const r = item.json;
  const ruta = r.ruta || 'SIN_RUTA';
  const monto = Number(r.monto) || 0;

  montoTotal += monto;

  if (!rutas[ruta]) {
    rutas[ruta] = {
      solicitudes: 0,
      monto_total: 0
    };
  }

  rutas[ruta].solicitudes++;
  rutas[ruta].monto_total += monto;

  if (ruta === 'APROBACION') {
    aprobaciones++;
  }
}

const totalSolicitudes = rows.length;

const tasaAprobacion = totalSolicitudes > 0
  ? (aprobaciones / totalSolicitudes) * 100
  : 0;

return [{
  json: {
    total_solicitudes: totalSolicitudes,
    solicitudes_por_ruta: rutas,
    monto_total_por_ruta: Object.fromEntries(
      Object.entries(rutas).map(([ruta, datos]) => [
        ruta,
        datos.monto_total
      ])
    ),
    monto_total_del_dia: montoTotal,
    tasa_aprobacion: tasaAprobacion
  }
}];

